<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Scout — Lead Discovery</title><style>body{margin:0;background:#08111f;color:#e8edf8;font:14px Inter,system-ui,sans-serif}header{padding:22px 5vw;border-bottom:1px solid #233149;display:flex;justify-content:space-between}h1{margin:0;font-size:21px}.sub{color:#91a2bd;margin-top:5px}.wrap{max-width:1280px;margin:28px auto;padding:0 22px}.search{display:flex;gap:10px;background:#101c2e;padding:16px;border-radius:12px}.search input{flex:1}.card{background:#101c2e;border:1px solid #233149;border-radius:12px;padding:18px;margin-top:18px}input,select,button{border-radius:7px;border:1px solid #334766;padding:10px;background:#0b1626;color:white}button{background:#3c72f5;border:0;font-weight:700;cursor:pointer}.muted{color:#91a2bd}.error{color:#ff9e9e}.stats{display:flex;gap:12px;flex-wrap:wrap}.stat{padding:14px;background:#15243a;border-radius:8px;min-width:120px}.stat b{font-size:21px;display:block}table{width:100%;border-collapse:collapse;margin-top:12px}th,td{text-align:left;border-bottom:1px solid #233149;padding:11px;vertical-align:top}th{color:#91a2bd;font-weight:600}.tag{background:#263d60;border-radius:99px;padding:4px 8px;font-size:12px}#login{max-width:420px;margin:12vh auto}.hidden{display:none}</style></head><body><header><div><h1>SCOUT <span class="muted">/ Lead Discovery</span></h1><div class="sub">Discover → normalize → store → organize → qualify</div></div><div id="who" class="muted">Secure workspace</div></header><main class="wrap"><section id="loginBox" class="card"><h2>Sign in to your workspace</h2><p class="muted">Lead data is isolated to your authenticated workspace.</p><input id="email" placeholder="Email" type="email"><input id="password" placeholder="Password" type="password"><button onclick="login()">Sign in</button><p id="loginErr" class="error"></p></section><section id="app" class="hidden"><div class="search"><input id="query" value="Restaurants in Lagos" aria-label="Business search"><select id="provider"><option value="google_places">Google Places · IMPLEMENTED</option></select><button onclick="search()">Search businesses</button><button onclick="exportCsv()">Export CSV</button></div><p id="message" class="muted">Search uses live Google Places results only. No synthetic businesses are shown.</p><div class="stats"><div class="stat"><span class="muted">Stored leads</span><b id="count">—</b></div><div class="stat"><span class="muted">Phone coverage</span><b id="phone">—</b></div><div class="stat"><span class="muted">Website coverage</span><b id="site">—</b></div></div><div class="card"><h2>Collections</h2><div class="search"><input id="collectionName" placeholder="New collection name"><button onclick="createCollection()">Create</button><select id="collectionSelect"></select><button onclick="addSelected()">Add selected leads</button></div><p id="collectionInfo" class="muted">Create a collection, select lead rows, then add them in bulk.</p></div><div class="card"><h2>Lead results</h2><div id="empty" class="muted">Your saved business leads will appear here.</div><table id="table" class="hidden"><thead><tr><th><input type="checkbox" onchange="selectAll(this.checked)"></th><th>Business</th><th>Category</th><th>Address</th><th>Contact</th><th>Pipeline</th></tr></thead><tbody id="rows"></tbody></table></div></section></main><script>let csrf='';const api='/api/v1/lead-discovery';async function request(path,opt={}){let r=await fetch(api+path,{...opt,headers:{'Content-Type':'application/json','X-CSRF-Token':csrf,...(opt.headers||{})}});let type=r.headers.get('content-type')||'';let d=type.includes('json')?await r.json():await r.blob();if(!r.ok)throw new Error(d.error||'Request failed');return d}async function login(){try{let r=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:email.value,password:password.value})});let d=await r.json();if(!r.ok)throw Error(d.error);csrf=d.csrfToken;who.textContent=d.user.email;document.getElementById('loginBox').classList.add('hidden');app.classList.remove('hidden');load()}catch(e){loginErr.textContent=e.message}}async function load(){try{let d=await request('/leads');render(d.leads);let c=await request('/coverage');count.textContent=c.leadCount;phone.textContent=(c.fields.find(x=>x.field==='Phone')||{}).coverage+'%';site.textContent=(c.fields.find(x=>x.field==='Website')||{}).coverage+'%';let collections=await request('/collections');collectionSelect.innerHTML=collections.collections.length?collections.collections.map(x=>`<option value="${x.id}">${escape(x.name)} (${x.leadCount})</option>`).join(''):'<option value="">No collections yet</option>'}catch(e){message.textContent=e.message}}function render(leads){empty.classList.toggle('hidden',leads.length);table.classList.toggle('hidden',!leads.length);rows.innerHTML=leads.map(x=>`<tr><td><input class="leadSelect" type="checkbox" value="${x.id}"></td><td><b>${escape(x.name)}</b><br><small class="muted">${escape(x.source)}</small></td><td>${escape(x.category||'—')}</td><td>${escape(x.address||'—')}</td><td>${escape(x.phone||'—')}<br>${x.website?'<a href="'+escape(x.website)+'" target="_blank">Website</a>':'—'}</td><td><select onchange="status('${x.id}',this.value)">${['new','contacted','qualified','disqualified','converted'].map(s=>'<option '+(x.status===s?'selected':'')+'>'+s+'</option>').join('')}</select></td></tr>`).join('')}function escape(v){let d=document.createElement('div');d.textContent=v;return d.innerHTML}async function search(){message.textContent='Searching Google Places…';try{let d=await request('/search',{method:'POST',body:JSON.stringify({query:query.value,provider:provider.value})});message.textContent=`${d.results.length} live results · ${d.newLeadsCreated} new · ${d.duplicatesDetected} existing records refreshed`;await load()}catch(e){message.textContent=e.message}}async function status(id,v){try{await request('/leads/'+id+'/status',{method:'PATCH',body:JSON.stringify({status:v})})}catch(e){message.textContent=e.message;load()}}function selectAll(on){document.querySelectorAll('.leadSelect').forEach(x=>x.checked=on)}async function createCollection(){let name=collectionName.value.trim();if(!name)return collectionInfo.textContent='Enter a collection name.';try{await request('/collections',{method:'POST',body:JSON.stringify({name})});collectionName.value='';collectionInfo.textContent='Collection created.';load()}catch(e){collectionInfo.textContent=e.message}}async function addSelected(){let id=collectionSelect.value,leadIds=[...document.querySelectorAll('.leadSelect:checked')].map(x=>x.value);if(!id)return collectionInfo.textContent='Create or select a collection.';if(!leadIds.length)return collectionInfo.textContent='Select at least one lead.';try{let r=await request('/collections/'+id+'/leads',{method:'POST',body:JSON.stringify({leadIds})});collectionInfo.textContent=`${r.added} lead(s) added to the collection.`;document.querySelectorAll('.leadSelect').forEach(x=>x.checked=false);load()}catch(e){collectionInfo.textContent=e.message}}async function exportCsv(){try{let r=await fetch(api+'/export/csv',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:'{}'});if(!r.ok)throw Error('Export failed');let a=document.createElement('a');a.href=URL.createObjectURL(await r.blob());a.download='leads.csv';a.click()}catch(e){message.textContent=e.message}}</script></body></html>